    await completeResetCleanup(resetConnection, marker);
    installationToken = marker.value.token;
    finish();
    rememberRecordEditor();
    closeModal();
    resetScreen("اطلاعات پاک شد؛ برنامه با اطلاعات خالی دوباره باز می‌شود.");
